(7, 1, '2024-04-09 16:14:30', '2024-04-09 21:14:30', '<!-- wp:nextend/smartslider3 {\"slider\":\"6\"} -->\n<div class=\"wp-block-nextend-smartslider3\">[smartslider3 slider=\"6\"]</div>\n<!-- /wp:nextend/smartslider3 -->\n\n<!-- wp:blockart/section {\"clientId\":\"fc8336a0\",\"columns\":2,\"blockMargin\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"unit\":\"px\",\"top\":136},\"mobile\":{\"top\":68,\"unit\":\"px\",\"lock\":false},\"tablet\":{\"top\":68,\"unit\":\"px\",\"lock\":false}},\"blockPadding\":{\"dimension\":1,\"desktop\":{\"left\":15,\"right\":15,\"unit\":\"px\"},\"mobile\":{\"unit\":\"px\",\"lock\":false,\"right\":15,\"left\":15},\"tablet\":{\"top\":0,\"unit\":\"px\",\"lock\":false,\"right\":15,\"bottom\":0,\"left\":15}}} -->\n<div class=\"blockart-section blockart-section-fc8336a0\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"49407e73\",\"colWidth\":{\"desktop\":50,\"tablet\":50,\"mobile\":100}} -->\n<div class=\"blockart-column blockart-column-49407e73\"><div class=\"blockart-column-inner\"><!-- wp:blockart/heading {\"clientId\":\"aa8a3a44\",\"text\":\"Experience the Life of Beautiful Santorini\",\"color\":\"#303030\",\"alignment\":{\"tablet\":\"left\"},\"typography\":{\"typography\":1,\"weight\":600,\"size\":{\"desktop\":{\"value\":32,\"unit\":\"px\"},\"mobile\":{\"value\":26,\"unit\":\"px\"}},\"family\":\"Poppins\"}} -->\n<h2 class=\"blockart-heading blockart-heading-aa8a3a44\">Experience the Life of Beautiful Santorini</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:blockart/paragraph {\"clientId\":\"ba0f8c6e\",\"text\":\"Tozai is Japanese for \\u0022East-West.\\u0022 It epitomizes the welcome we offer our guests, combining western-style luxury with the best in Japanese cuisine and hospitality.\",\"alignment\":{\"tablet\":\"left\"},\"typography\":{\"typography\":1,\"weight\":400,\"size\":{\"desktop\":{\"value\":16,\"unit\":\"px\"},\"mobile\":{\"value\":16,\"unit\":\"px\"}},\"family\":\"Poppins\"},\"color\":\"#303030\",\"margin\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"top\":16,\"bottom\":16,\"unit\":\"px\"},\"mobile\":{\"bottom\":20,\"unit\":\"px\",\"lock\":false,\"top\":15}}} -->\n<p class=\"blockart-paragraph blockart-paragraph-ba0f8c6e\">Tozai is Japanese for \"East-West.\" It epitomizes the welcome we offer our guests, combining western-style luxury with the best in Japanese cuisine and hospitality.</p>\n<!-- /wp:blockart/paragraph -->\n\n<!-- wp:blockart/image {\"clientId\":\"7cf8bcff\",\"image\":{\"url\":\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/04/pexels-aden-ardenrich-181745-581299-scaled.jpg\",\"id\":1225,\"height\":2560,\"width\":1705,\"alt\":\"\"},\"alignment\":{\"tablet\":\"left\"},\"border\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":10,\"right\":10,\"bottom\":10,\"left\":10,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true}}},\"width\":{\"desktop\":{\"value\":1920,\"unit\":\"px\"},\"tablet\":{\"unit\":\"%\",\"value\":100},\"mobile\":{\"unit\":\"%\",\"value\":100}},\"maxWidth\":{\"tablet\":{\"value\":1920,\"unit\":\"px\"}},\"height\":{\"desktop\":{\"value\":565,\"unit\":\"px\"},\"mobile\":{\"unit\":\"%\",\"value\":50}},\"blockMargin\":{\"dimension\":1,\"desktop\":{\"lock\":true},\"tablet\":{\"bottom\":20,\"unit\":\"px\",\"lock\":false}}} -->\n<figure class=\"blockart-image blockart-image-7cf8bcff\"><img class=\"wp-image-1225 hover-effect-static filter-none mask mask-none\" src=\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/04/pexels-aden-ardenrich-181745-581299-scaled.jpg\" alt=\"\" height=\"2560\" width=\"1705\"/></figure>\n<!-- /wp:blockart/image --></div></div>\n<!-- /wp:blockart/column -->\n\n<!-- wp:blockart/column {\"clientId\":\"7a934c98\",\"colWidth\":{\"desktop\":50,\"tablet\":50,\"mobile\":100}} -->\n<div class=\"blockart-column blockart-column-7a934c98\"><div class=\"blockart-column-inner\"><!-- wp:blockart/image {\"clientId\":\"8023b3a0\",\"image\":{\"url\":\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/04/pexels-berk-ozdemir-3779816-scaled.jpg\",\"id\":1202,\"height\":2560,\"width\":1810,\"alt\":\"Traditional Japanese building\"},\"alignment\":{\"tablet\":\"left\"},\"border\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":10,\"right\":10,\"bottom\":10,\"left\":10,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true}}},\"width\":{\"desktop\":{\"value\":1783,\"unit\":\"px\"},\"mobile\":{\"unit\":\"%\",\"value\":100},\"tablet\":{\"unit\":\"%\",\"value\":100}},\"maxWidth\":{\"tablet\":{\"unit\":\"%\"}},\"height\":{\"desktop\":{\"value\":565,\"unit\":\"px\"},\"mobile\":{\"unit\":\"%\",\"value\":50}}} -->\n<figure class=\"blockart-image blockart-image-8023b3a0\"><img class=\"wp-image-1202 hover-effect-static filter-none mask mask-none\" src=\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/04/pexels-berk-ozdemir-3779816-scaled.jpg\" alt=\"Traditional Japanese building\" height=\"2560\" width=\"1810\"/></figure>\n<!-- /wp:blockart/image -->\n\n<!-- wp:blockart/paragraph {\"clientId\":\"3acf7508\",\"text\":\"Escape from the bustle and stress of everyday life, and relax in the comfort and tranquility of Tozai Hotel\'s guest rooms and gardens. Our expert chefs are ready to delight your taste buds with sashimi and sushi, made only from the choicest cuts of fish delivered daily from Tsukiji market in Tokyo.\",\"alignment\":{\"tablet\":\"left\"},\"typography\":{\"typography\":1,\"weight\":400,\"size\":{\"desktop\":{\"value\":16,\"unit\":\"px\"},\"mobile\":{\"value\":16,\"unit\":\"px\"}},\"family\":\"Poppins\"},\"color\":\"#303030\",\"margin\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"unit\":\"px\",\"top\":20,\"bottom\":20}}} -->\n<p class=\"blockart-paragraph blockart-paragraph-3acf7508\">Escape from the bustle and stress of everyday life, and relax in the comfort and tranquility of Tozai Hotel\'s guest rooms and gardens. Our expert chefs are ready to delight your taste buds with sashimi and sushi, made only from the choicest cuts of fish delivered daily from Tsukiji market in Tokyo.</p>\n<!-- /wp:blockart/paragraph -->\n\n<!-- wp:blockart/button {\"clientId\":\"a047e5e2\",\"justification\":{\"desktop\":\"left\",\"tablet\":\"left\"},\"orientation\":{\"desktop\":\"horizontal\"}} -->\n<div class=\"blockart-buttons blockart-buttons-a047e5e2 is-wrap is-horizontal justify-left justify-left-md\"><!-- wp:blockart/button-inner {\"clientId\":\"7e4d9b8e\",\"text\":\"Read More\",\"size\":\"custom\",\"padding\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"top\":16,\"right\":36,\"bottom\":16,\"left\":36,\"unit\":\"px\"}},\"typography\":{\"typography\":1,\"weight\":500,\"size\":{\"desktop\":{\"value\":16,\"unit\":\"px\"},\"mobile\":{\"value\":16,\"unit\":\"px\"}},\"family\":\"Poppins\"},\"color1\":\"#000000\",\"color2\":\"#ffffff\",\"hoverColor1\":\"#ffffff\",\"hoverColor2\":\"#000000\",\"background1\":{\"background\":1,\"type\":\"color\",\"color\":\"rgba(255,255,255,0.01)\"},\"hoverBackground1\":{\"background\":1,\"type\":\"color\",\"color\":\"#0b70f4\"},\"hoverBackground2\":{\"background\":1,\"type\":\"color\",\"color\":\"#ffffff\"},\"border1\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true,\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\"}},\"type\":\"solid\",\"color\":\"#000000\"},\"hoverBorder1\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true,\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\"}},\"type\":\"solid\",\"color\":\"rgba(255,255,255,0.01)\"},\"border2\":{\"border\":1,\"color\":\"#ffffff\",\"type\":\"solid\",\"radius\":{\"desktop\":{\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\",\"lock\":true}},\"size\":{\"desktop\":{\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\",\"lock\":true}}}} -->\n<div class=\"blockart-button blockart-button-7e4d9b8e \"><a class=\"blockart-button-link is-custom is-style-filled\">Read More</a></div>\n<!-- /wp:blockart/button-inner --></div>\n<!-- /wp:blockart/button --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->\n\n<!-- wp:blockart/section {\"clientId\":\"b55db512\",\"hasModal\":true,\"columns\":1} -->\n<div class=\"blockart-section blockart-section-b55db512\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"4d7b2581\",\"colWidth\":{\"desktop\":100,\"tablet\":100,\"mobile\":100}} -->\n<div class=\"blockart-column blockart-column-4d7b2581\"><div class=\"blockart-column-inner\"></div></div>\n<!-- /wp:blockart/column -->\n\n<!-- wp:blockart/column {\"clientId\":\"0af5ce10\"} -->\n<div class=\"blockart-column blockart-column-0af5ce10\"><div class=\"blockart-column-inner\"></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->\n\n<!-- wp:nextend/smartslider3 {\"slider\":\"2\"} -->\n<div class=\"wp-block-nextend-smartslider3\">[smartslider3 slider=\"2\"]</div>\n<!-- /wp:nextend/smartslider3 -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Home', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2024-05-03 22:46:47', '2024-05-04 03:46:47', '', 0, 'https://kbotabara.bitlampsites.com/iwp/tozai-hotel/?page_id=7', 0, 'page', '', 0),
