(1242, 1, '2024-04-30 15:25:12', '2024-04-30 20:25:12', '<!-- wp:nextend/smartslider3 {\"slider\":\"6\"} -->\n<div class=\"wp-block-nextend-smartslider3\">[smartslider3 slider=\"6\"]</div>\n<!-- /wp:nextend/smartslider3 -->\n\n<!-- wp:blockart/section {\"clientId\":\"da31e17f\",\"columns\":2,\"blockMargin\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"unit\":\"px\",\"top\":136},\"mobile\":{\"top\":68,\"unit\":\"px\",\"lock\":false},\"tablet\":{\"top\":68,\"unit\":\"px\",\"lock\":false}},\"blockPadding\":{\"dimension\":1,\"desktop\":{\"left\":15,\"right\":15,\"unit\":\"px\"},\"mobile\":{\"unit\":\"px\",\"lock\":false,\"right\":15,\"left\":15},\"tablet\":{\"top\":0,\"unit\":\"px\",\"lock\":false,\"right\":15,\"bottom\":0,\"left\":15}}} -->\n<div class=\"blockart-section blockart-section-da31e17f\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"11331e4c\",\"colWidth\":{\"desktop\":50,\"tablet\":50,\"mobile\":100}} -->\n<div class=\"blockart-column blockart-column-11331e4c\"><div class=\"blockart-column-inner\"><!-- wp:blockart/heading {\"clientId\":\"961eb803\",\"text\":\"Experience the Life of Beautiful Santorini\",\"color\":\"#303030\",\"alignment\":{\"tablet\":\"left\"},\"typography\":{\"typography\":1,\"weight\":600,\"size\":{\"desktop\":{\"value\":32,\"unit\":\"px\"},\"mobile\":{\"value\":26,\"unit\":\"px\"}},\"family\":\"Poppins\"}} -->\n<h2 class=\"blockart-heading blockart-heading-961eb803\">Experience the Life of Beautiful Santorini</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:blockart/paragraph {\"clientId\":\"809e78e6\",\"text\":\"Tozai is Japanese for \\u0022East-West.\\u0022 It epitomizes the welcome we offer our guests, combining western-style luxury with the best in Japanese cuisine and hospitality.\",\"alignment\":{\"tablet\":\"left\"},\"typography\":{\"typography\":1,\"weight\":400,\"size\":{\"desktop\":{\"value\":16,\"unit\":\"px\"},\"mobile\":{\"value\":16,\"unit\":\"px\"}},\"family