\n<div style=\"height:143px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->\n\n<!-- wp:blockart/spacing {\"clientId\":\"ffaad25b\"} -->\n<div class=\"blockart-spacing blockart-spacing-ffaad25b\"><div class=\"blockart-spacing-inner\"></div></div>\n<!-- /wp:blockart/spacing -->\n\n<!-- wp:blockart/heading {\"clientId\":\"04fbd07a\",\"markup\":\"h1\",\"text\":\"Reservations\",\"alignment\":{\"desktop\":\"center\"},\"typography\":{\"typography\":1,\"weight\":700,\"family\":\"Poppins\",\"size\":{\"desktop\":{\"value\":39,\"unit\":\"px\"}}}} -->\n<h1 class=\"blockart-heading blockart-heading-04fbd07a\">Reservations</h1>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:blockart/section {\"clientId\":\"4337ee26\",\"columns\":2,\"childRow\":true,\"blockMargin\":{\"desktop\":{\"lock\":false,\"top\":100,\"unit\":\"px\"},\"tablet\":{\"top\":50,\"unit\":\"px\",\"lock\":false},\"mobile\":{\"top\":50,\"unit\":\"px\",\"lock\":false},\"dimension\":1},\"blockPadding\":{\"desktop\":{\"lock\":false,\"right\":0,\"left\":0,\"unit\":\"px\"},\"tablet\":{\"right\":20,\"unit\":\"px\",\"lock\":false,\"left\":20},\"mobile\":{\"right\":10,\"unit\":\"px\",\"lock\":false,\"left\":10},\"dimension\":1}} -->\n<div class=\"blockart-section blockart-section-4337ee26\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"e3976217\",\"blockMargin\":{\"desktop\":{\"lock\":true,\"unit\":\"px\"},\"tablet\":{\"bottom\":50,\"unit\":\"px\",\"lock\":false},\"mobile\":{\"bottom\":50,\"unit\":\"px\",\"lock\":false},\"dimension\":1},\"blockPadding\":{\"desktop\":{\"lock\":true,\"unit\":\"px\"},\"dimension\":1}} -->\n<div class=\"blockart-column blockart-column-e3976217\"><div class=\"blockart-column-inner\"><!-- wp:shortcode -->\n[everest_form id=\"1321\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:blockart/column -->\n\n<!-- wp:blockart/column {\"clientId\":\"e88a0f3e\",\"blockMargin\":{\"desktop\":{\"lock\":true},\"dimension\":1},\"blockPadding\":{\"mobile\":{\"top\":20,\"unit\":\"px\",\"lock\":false,\"right\":0,\"bottom\":20,\"left\":0},\"tablet\":{\"top\":20,\"unit\":\"px\",\"lock\":false,\"right\":0,\"bottom\":0,\"left\":0},\"dimension\":1}} -->\n<div class=\"blockart-column blockart-column-e88a0f3e\"><div class=\"blockart-column-inner\"><!-- wp:blockart/heading {\"clientId\":\"d055ea60\",\"text\":\"Booking Terms and Conditions\\u003cbr\\u003eReservations and Cancellation Policy:\",\"alignment\":{\"desktop\":\"left\"},\"size\":\"small\",\"typography\":{\"typography\":1,\"weight\":\"600\",\"family\":\"Poppins\",\"size\":{\"desktop\":{\"value\":20,\"unit\":\"px\"}},\"lineHeight\":{\"desktop\":{\"value\":28,\"unit\":\"px\"}}}} -->\n<h2 class=\"blockart-heading blockart-heading-d055ea60 is-small\">Booking Terms and Conditions<br>Reservations and Cancellation Policy:</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>All reservations are subject to availability and must be confirm with a valid credit/debit card.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cancellations made 2 days prior to the scheduled arrival date will not incur any charges.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cancellations made within 1 day of the schedule arrival date will result in a charge equivalent to 20% of the total booking amount.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>No-shows or early departures will be charged the full booking amount.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Modification of Reservations:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:blockart/heading {\"clientId\":\"46c549f8\",\"text\":\"Changes to reservation dates or room types are subject to availability.\",\"typography\":{\"typography\":1,\"weight\":\"600\",\"size\":{\"desktop\":{\"value\":15,\"unit\":\"px\"}},\"lineHeight\":{\"desktop\":{\"value\":20,\"unit\":\"px\"}}}} -->\n<h2 class=\"blockart-heading blockart-heading-46c549f8\">Changes to reservation dates or room types are subject to availability.</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>A valid credit/debit card is require to secure a reservation.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>A pre-authorization may be perform on the card provided to validate its authenticity.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Payment for the entire stay, including any applicable taxes and fees, will be settle upon check-in.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->', 'Reservations', '', 'publish', 'closed', 'closed', '', 'reservation', '', '', '2024-05-14 15:33:07', '2024-05-14 20:33:07', '', 0, 'https://kbotabara.bitlampsites.com/iwp/tozai-hotel/?page_id=1315', 0, 'page', '', 0),
(1316, 1, '2024-05-05 00:35:44', '2024-05-05 05:35:44', '<!-- wp:yoast-seo/breadcrumbs /-->\n\n<!-- wp:blockart/section {\"clientId\":\"11e8bf93\",\"columns\":1,\"blockMargin\":{\"desktop\":{\"lock\":true},\"mobile\":{\"unit\":\"px\",\"lock\":true},\"dimension\":1},\"blockPadding\":{\"desktop\":{\"lock\":false,\"top\":100,\"bottom\":100,\"unit\":\"px\"},\"tablet\":{\"top\":50,\"unit\":\"px\",\"lock\":false,\"bottom\":50,\"right\":10,\"left\":10},\"mobile\":{\"top\":50,\"unit\":\"px\",\"lock\":false,\"bottom\":50},\"dimension\":1}} -->\n<div class=\"blockart-section blockart-section-11e8bf93\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"cf1d8dd5\",\"colWidth\":{\"desktop\":100,\"tablet\":100,\"mobile\":100},\"blockMargin\":{\"desktop\":{\"lock\":true},\"dimension\":1},\"blockPadding\":{\"tablet\":{\"unit\":\"px\",\"lock\":true},\"mobile\":{\"top\":0,\"unit\":\"px\",\"lock\":true,\"right\":0,\"bottom\":0,\"left\":0},\"desktop\":{\"top\":0,\"unit\":\"px\",\"lock\":false},\"dimension\":1}} -->\n<div class=\"blockart-column blockart-column-cf1d8dd5\"><div class=\"blockart-column-inner\"><!-- wp:blockart/heading {\"clientId\":\"7ccaab9a\",\"markup\":\"h1\",\"text\":\"Reservations\",\"alignment\":{\"desktop\":\"center\"},\"typography\":{\"typography\":1,\"weight\":700,\"family\":\"Poppins\",\"size\":{\"desktop\":{\"value\":39,\"unit\":\"px\"}}}} -->\n<h1 class=\"blockart-heading blockart-heading-7ccaab9a\">Reservations</h1>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:blockart/section {\"clientId\":\"7bbd5cc5\",\"columns\":1,\"childRow\":true} -->\n<div class=\"blockart-section blockart-section-7bbd5cc5\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"b63021db\",\"colWidth\":{\"desktop\":100,\"tablet\":100,\"mobile\":100}} -->\n<div class=\"blockart-column blockart-column-b63021db\"><div class=\"blockart-column-inner\"><!-- wp:paragraph -->\n<p>Japanese cuisine is not only a feast for the taste buds, but for the eyes. Presentation is an important part of a chef\'s skills. If you enjoy fish, you\'ll love the restaurant at Tozai Hotel, where our master chefs will select the choicest cuts of the day\'s fresh catch to serve you mouth-watering&nbsp;<em>sashimi</em>&nbsp;and&nbsp;<em>sushi</em>.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->\n\n<!-- wp:blockart/section {\"clientId\":\"2c2d9e71\",\"columns\":2,\"childRow\":true,\"blockMargin\":{\"desktop\":{\"lock\":false,\"top\":100,\"unit\":\"px\"},\"tablet\":{\"top\":50,\"unit\":\"px\",\"lock\":false},\"mobile\":{\"top\":50,\"unit\":\"px\",\"lock\":false},\"dimension\":1},\"blockPadding\":{\"desktop\":{\"lock\":false,\"right\":0,\"left\":0,\"unit\":\"px\"},\"tablet\":{\"right\":20,\"unit\":\"px\",\"lock\":false,\"left\":20},\"mobile\":{\"right\":10,\"unit\":\"px\",\"lock\":false,\"left\":10},\"dimension\":1}} -->\n<div class=\"blockart-section blockart-section-2c2d9e71\"><div class=\"blockart-container\"><div class=\"blockart-section-inner\"><!-- wp:blockart/column {\"clientId\":\"bf65d2de\",\"blockMargin\":{\"desktop\":{\"lock\":true,\"unit\":\"px\"},\"tablet\":{\"bottom\":50,\"unit\":\"px\",\"lock\":false},\"mobile\":{\"bottom\":50,\"unit\":\"px\",\"lock\":false},\"dimension\":1},\"blockPadding\":{\"desktop\":{\"lock\":true,\"unit\":\"px\"},\"dimension\":1}} -->\n<div class=\"blockart-column blockart-column-bf65d2de\"><div class=\"blockart-column-inner\"><!-- wp:blockart/heading {\"clientId\":\"ec9c1307\",\"text\":\"Blend of artistry and tradition\",\"typography\":{\"typography\":1,\"weight\":\"600\",\"family\":\"Poppins\",\"size\":{\"desktop\":{\"value\":30,\"unit\":\"px\"}},\"lineHeight\":{\"desktop\":{\"value\":28,\"unit\":\"px\"}}}} -->\n<h2 class=\"blockart-heading blockart-heading-ec9c1307\">Blend of artistry and tradition</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:paragraph -->\n<p>[acf field=\"last_name\"]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:blockart/button {\"clientId\":\"2b0c4695\",\"justification\":{\"desktop\":\"left\",\"tablet\":\"left\"},\"orientation\":{\"desktop\":\"horizontal\"}} -->\n<div class=\"blockart-buttons blockart-buttons-2b0c4695 is-wrap is-horizontal justify-left justify-left-md\"><!-- wp:blockart/button-inner {\"clientId\":\"d8e383dc\",\"text\":\"Read More\",\"size\":\"custom\",\"padding\":{\"dimension\":1,\"desktop\":{\"lock\":false,\"top\":16,\"right\":36,\"bottom\":16,\"left\":36,\"unit\":\"px\"}},\"typography\":{\"typography\":1,\"weight\":500,\"size\":{\"desktop\":{\"value\":16,\"unit\":\"px\"},\"mobile\":{\"value\":16,\"unit\":\"px\"}},\"family\":\"Poppins\"},\"color1\":\"#000000\",\"color2\":\"#ffffff\",\"hoverColor1\":\"#ffffff\",\"hoverColor2\":\"#000000\",\"background1\":{\"background\":1,\"type\":\"color\",\"color\":\"rgba(255,255,255,0.01)\"},\"hoverBackground1\":{\"background\":1,\"type\":\"color\",\"color\":\"#0b70f4\"},\"hoverBackground2\":{\"background\":1,\"type\":\"color\",\"color\":\"#ffffff\"},\"border1\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true,\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\"}},\"type\":\"solid\",\"color\":\"#000000\"},\"hoverBorder1\":{\"border\":1,\"radius\":{\"desktop\":{\"lock\":true,\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\"}},\"size\":{\"desktop\":{\"lock\":true,\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\"}},\"type\":\"solid\",\"color\":\"rgba(255,255,255,0.01)\"},\"border2\":{\"border\":1,\"color\":\"#ffffff\",\"type\":\"solid\",\"radius\":{\"desktop\":{\"top\":5,\"right\":5,\"bottom\":5,\"left\":5,\"unit\":\"px\",\"lock\":true}},\"size\":{\"desktop\":{\"top\":2,\"right\":2,\"bottom\":2,\"left\":2,\"unit\":\"px\",\"lock\":true}}}} -->\n<div class=\"blockart-button blockart-button-d8e383dc \"><a class=\"blockart-button-link is-custom is-style-filled\">Read More</a></div>\n<!-- /wp:blockart/button-inner --></div>\n<!-- /wp:blockart/button -->\n\n<!-- wp:spacer {\"height\":\"133px\"} -->\n<div style=\"height:133px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:blockart/image {\"clientId\":\"e0b318e7\",\"image\":{\"url\":\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/05/neon-in-a-japanese-restaurant-18176489-1024x683.jpg\",\"id\":1277,\"height\":683,\"width\":1024,\"alt\":\"Neon in a Japanese Restaurant\"}} -->\n<figure class=\"blockart-image blockart-image-e0b318e7\"><img class=\"wp-image-1277 hover-effect-static filter-none mask mask-none\" src=\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/05/neon-in-a-japanese-restaurant-18176489-1024x683.jpg\" alt=\"Neon in a Japanese Restaurant\" height=\"683\" width=\"1024\"/></figure>\n<!-- /wp:blockart/image --></div></div>\n<!-- /wp:blockart/column -->\n\n<!-- wp:blockart/column {\"clientId\":\"7d8b2351\",\"blockMargin\":{\"desktop\":{\"lock\":true},\"dimension\":1},\"blockPadding\":{\"mobile\":{\"top\":20,\"unit\":\"px\",\"lock\":false,\"right\":0,\"bottom\":20,\"left\":0},\"tablet\":{\"top\":20,\"unit\":\"px\",\"lock\":false,\"right\":0,\"bottom\":0,\"left\":0},\"dimension\":1}} -->\n<div class=\"blockart-column blockart-column-7d8b2351\"><div class=\"blockart-column-inner\"><!-- wp:blockart/image {\"clientId\":\"06592dc5\",\"image\":{\"url\":\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/05/woman-eating-sushi-in-a-restaurant-15433927-683x1024.jpg\",\"id\":1276,\"height\":1024,\"width\":683,\"alt\":\"Woman Eating Sushi in a Restaurant\"}} -->\n<figure class=\"blockart-image blockart-image-06592dc5\"><img class=\"wp-image-1276 hover-effect-static filter-none mask mask-none\" src=\"https://kbotabara.bitlampsites.com/iwp/tozai-hotel/wp-content/uploads/2024/05/woman-eating-sushi-in-a-restaurant-15433927-683x1024.jpg\" alt=\"Woman Eating Sushi in a Restaurant\" height=\"1024\" width=\"683\"/></figure>\n<!-- /wp:blockart/image -->\n\n<!-- wp:blockart/spacing {\"clientId\":\"6901ae06\"} -->\n<div class=\"blockart-spacing blockart-spacing-6901ae06\"><div class=\"blockart-spacing-inner\"></div></div>\n<!-- /wp:blockart/spacing -->\n\n<!-- wp:blockart/heading {\"clientId\":\"0b9ba7aa\",\"text\":\"Saké—the Perfect Accompaniment\",\"alignment\":{\"desktop\":\"left\"},\"size\":\"small\",\"typography\":{\"typography\":1,\"weight\":\"600\",\"family\":\"Poppins\",\"size\":{\"desktop\":{\"value\":30,\"unit\":\"px\"}},\"lineHeight\":{\"desktop\":{\"value\":28,\"unit\":\"px\"}}}} -->\n<h2 class=\"blockart-heading blockart-heading-0b9ba7aa is-small\">Saké—the Perfect Accompaniment</h2>\n<!-- /wp:blockart/heading -->\n\n<!-- wp:paragraph -->\n<p>Japanese rice wine, saké, makes the perfect accompaniment to your meal. Although saké can be drunk hot, connoisseurs prefer to drink it cold or on the rocks. Drinking saké cold allows you to appreciate the subtle differences in taste that come from the rice variety and water used in the fermentation process.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section --></div></div>\n<!-- /wp:blockart/column --></div></div></div>\n<!-- /wp:blockart/section -->', 'Reservations', '', 'inherit', 'closed', 'closed', '', '1315-revision-v1', '', '', '2024-05-05 00:35:44', '2024-05-05 05:35:44', '', 1315, 'https://kbotabara.bitlampsites.com/iwp/tozai-hotel/?p=1316', 0, 'revision', '', 0);
