(155, 2, '2007-09-04 10:47:47', '2007-09-04 17:47:47', 'Repository-hosted Themes are required to support display of comments on static Pages as well as on single blog Posts.  This static Page has comments, and these comments should be displayed.\nIf the Theme includes a custom option to prevent static Pages from displaying comments, such option must be disabled (i.e. so that static Pages display comments) by default.\nAlso, verify that this Page does not display taxonomy information (e.g. categories or tags) or time-stamp information (Page publish date/time).', 'Page with comments', '', 'publish', 'open', 'closed', '', 'page-with-comments', '', '', '2007-09-04 10:47:47', '2007-09-04 17:47:47', '', 1725, 'https://wpthemetestdata.wordpress.com/page-with-comments/', 3, 'page', '', 3),
(156, 2, '2007-09-04 10:48:10', '2007-09-04 17:48:10', 'This static Page is set not to allow comments. Verify that the Page does not display a comment list, comment reply links, or comment reply form.\nAlso, verify that the Page does not display a \"comments are closed\" type message. Such messages are not suitable for static Pages, and should only be used on blog Posts.', 'Page with comments disabled', '', 'publish', 'closed', 'closed', '', 'page-with-comments-disabled', '', '', '2007-09-04 10:48:10', '2007-09-04 17:48:10', '', 1725, 'https://wpthemetestdata.wordpress.com/page-with-comments-disabled/', 4, 'page', '', 0),
(163, 3, '2023-01-16 07:08:31', '2023-01-16 07:08:31', '<!-- wp:paragraph -->\n<p>This test post was generated using the block theme Emptytheme in WordPress 6.1.1.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"fontSize\":\"small\"} -->\n<h2 class=\"has-small-font-size\">Small H2 Heading</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"fontSize\":\"medium\"} -->\n<h2 class=\"has-medium-font-size\">Medium H2 Heading</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"has-large-font-size\">Large H2 Heading</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"has-large-font-size\">Extra Large H2 Heading</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\">Small paragraph</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Medium paragraph</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Large paragraph</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"x-large\"} -->\n<p class=\"has-x-large-font-size\">Extra Large paragraph</p>\n<!-- /wp:paragraph -->\n	', 'WP 6.1 Font size scale', '', 'publish', 'open', 'open', '', 'wp-6-1-font-size-scale', '', '', '2023-01-16 07:08:31', '2023-01-16 07:08:31', '', 0, 'https://wpthemetestdata.wordpress.com/wp-6-1-font-size-scale/', 0, 'post', '', 0),
