(104, 63, '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:2000;s:6:\"height\";i:1543;s:4:\"file\";s:24:\"2024/10/youngpicture.jpg\";s:8:\"filesize\";i:427036;s:5:\"sizes\";a:8:{s:6:\"medium\";a:5:{s:4:\"file\";s:24:\"youngpicture-300x231.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:231;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:13337;}s:5:\"large\";a:5:{s:4:\"file\";s:25:\"youngpicture-1024x790.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:790;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:106747;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:24:\"youngpicture-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:6274;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:24:\"youngpicture-768x593.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:593;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:65903;}s:9:\"1536x1536\";a:5:{s:4:\"file\";s:26:\"youngpicture-1536x1185.jpg\";s:5:\"width\";i:1536;s:6:\"height\";i:1185;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:204400;}s:15:\"adverts-gallery\";a:5:{s:4:\"file\";s:24:\"youngpicture-389x300.jpg\";s:5:\"width\";i:389;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:20601;}s:12:\"adverts-list\";a:5:{s:4:\"file\";s:24:\"youngpicture-310x239.jpg\";s:5:\"width\";i:310;s:6:\"height\";i:239;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:14222;}s:24:\"adverts-upload-thumbnail\";a:5:{s:4:\"file\";s:24:\"youngpicture-136x105.jpg\";s:5:\"width\";i:136;s:6:\"height\";i:105;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:3901;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
