(14, 1, '2024-10-07 14:51:20', '2024-10-07 14:51:20', '<!-- wp:columns {\"metadata\":{\"name\":\"Author Parts\",\"categories\":[],\"patternName\":\"core/block/62\"},\"className\":\"author-parts\"} -->\n<div class=\"wp-block-columns author-parts\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-large-font-size\"></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"8px\"} -->\n<div style=\"height:8px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":70,\"width\":\"397px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"https://kbotabara.bitlampsites.com/wpd/final-project/wp-content/uploads/2024/10/contact-1024x576.webp\" alt=\"\" class=\"wp-image-70\" style=\"width:397px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>LIZ PICHON FANMAIL<br></strong>Scholastic Children\'s Books<br>1 London Bridge<br>London<br>SE1 9BG</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Publisher: <a href=\"https://www.scholastic.co.uk/contactus\">Scholastic Childrens Books:</a><br><br>BOOK AGENT: Caroline Walsh</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>David Higham Associates<br>7th Floor, Waverley House,<br>7-12 Noel Street<br>London W1F 8GQ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://www.davidhigham.co.uk/contact/\">dha@davidhigham.co.uk</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tel: 020 7434 5900</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>FILM/TV/SCRIPT AGENT: Georgina Ruffhead</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The Hawthorn Agency<br>Studio 103, Babel Studios<br>158b Kentish Town