(64, 'provider_cart', NULL, 'enabled', 'email', 'appointment', NULL, NULL, NULL, 'provider', 'Cart Purchase', '<p>Hi <strong>%employee_full_name%</strong>,</p><p><br></p><p>Customer <strong>%customer_full_name%</strong> has successfully scheduled several appointments. The details about bookings are shown below.</p><p><br></p><p>%cart_appointments_details%</p><p><br></p><p>Thank you,</p><p><strong>%company_name%</strong></p>', NULL, 0, NULL, NULL),
(65, 'provider_cart', NULL, 'enabled', 'sms', 'appointment', NULL, NULL, NULL, 'provider', 'NULL', 'Hi %employee_full_name%,\n\nCustomer %customer_full_name% has successfully scheduled several appointments.\n                     \nThank you, %company_name%', NULL, 0, NULL, NULL),
(66, 'customer_event_waiting', NULL, 'enabled', 'email', 'event', NULL, NULL, NULL, 'customer', '%event_name% Waiting List joined', 'Dear <strong>%customer_full_name%</strong>,<br><br>You have successfully joined the Waiting List for the\n                 <strong>%event_name%</strong> event at\n                 <strong>%event_location%</strong> on\n                 <strong>%event_start_date_time%</strong>.<br><br>\n                 Thank you for choosing our company,<br><strong>%company_name%</strong>', NULL, 0, NULL, NULL),
(67, 'customer_event_waiting', NULL, 'enabled', 'sms', 'event', NULL, NULL, NULL, 'customer', '%event_name% Waiting List joined', 'Dear %customer_full_name%,\n                \nYou have successfully joined the Waiting List for the %event_name% event at %event_location% on %event_start_date_time%.\n\nThank you for choosing our company,\n%company_name%', NULL, 0, NULL, NULL),
(68, 'provider_event_waiting', NULL, 'enabled', 'email', 'event', NULL, NULL, NULL, 'provider', '%event_name% Waiting List joined', 'Hi <strong>%employee_full_name%</strong>,<br><br>A new attendee has been added to the waiting list for\n                 <strong>%event_name%</strong> Event at\n                 <strong>%event_location%</strong> on\n                 <strong>%event_start_date_time%</strong>.<br><br>\n                 Thank you,<br><strong>%company_name%</strong>', NULL, 0, NULL, NULL),
