(106, 'customer_appointment_updated', NULL, 'enabled', 'email', 'appointment', NULL, NULL, NULL, 'customer', '%service_name% Appointment Details Changed', 'Dear <strong>%customer_full_name%</strong>,<br><br>Details of the appointment on <strong>%appointment_date_time%</strong> have changed: <br>\n                        <ul>\n                            <li>Employee: <strong>%employee_full_name%</strong></li>\n                            <li>Location: <strong>%location_name%</strong></li>\n                            <li>Extras: <strong>%service_extras%</strong></li>\n                        </ul><br>Thank you for choosing our company,<br>\n                    <strong>%company_name%</strong>', NULL, 0, NULL, NULL),
(107, 'provider_appointment_updated', NULL, 'enabled', 'email', 'appointment', NULL, NULL, NULL, 'provider', '%service_name% Appointment Details Changed', 'Hi <strong>%employee_full_name%</strong>,<br><br>Details of the appointment on <strong>%appointment_date_time%</strong>  have changed:\n                       <br>\n                        <ul>\n                            <li>Customers: <strong>%customer_full_name%</strong></li>\n                            <li>Location: <strong>%location_name%</strong></li>\n                            <li>Extras: <strong>%service_extras%</strong></li>\n                        </ul><br>Thank you,<br>\n                    <strong>%company_name%</strong>', NULL, 0, NULL, NULL),
(108, 'customer_appointment_updated', NULL, 'enabled', 'sms', 'appointment', NULL, NULL, NULL, 'customer', '%service_name% Appointment Details Changed', 'Dear %customer_full_name%,\n\nDetails of the appointment on %appointment_date_time% have changed:\n    Employee: %employee_full_name%\n    Location: %location_name%\n    Extras: %service_extras%\n    \nThank you for choosing our company,\n%company_name%', NULL, 0, NULL, NULL),
(109, 'provider_appointment_updated', NULL, 'enabled', 'sms', 'appointment', NULL, NULL, NULL, 'provider', '%service_name% Appointment Details Changed', 'Hi %employee_full_name%,\n                \nDetails of the appointment on %appointment_date_time% have changed:\n    Customers: %customer_full_name%,\n    Location: %location_name%,\n    Extras: %service_extras%\n    \nThank you,\n%company_name%', NULL, 0, NULL, NULL),
