(112, 'customer_event_updated', NULL, 'enabled', 'email', 'event', NULL, NULL, NULL, 'customer', '%event_name% Event Details Changed', 'Dear <strong>%customer_full_name%</strong>,<br><br>Details of the event on <strong>%event_start_date_time%</strong> have changed:\n                    <ul>\n                        <li>Organizer: <strong>%employee_full_name%</strong></li>\n                        <li>Location: <strong>%location_name%</strong></li>\n                    </ul><br>Thank you for choosing our company, <br>\n                    <strong>%company_name%</strong>', NULL, 0, NULL, NULL),
(113, 'provider_event_updated', NULL, 'enabled', 'email', 'event', NULL, NULL, NULL, 'provider', '%event_name% Event Details Changed', 'Hi <strong>%employee_full_name%</strong>,<br><br>Details of the event on <strong>%event_start_date_time%</strong> have changed:\n                        <ul>\n                            <li>Description: <strong>%event_description%</strong></li>\n                            <li>Location: <strong>%location_name%</strong></li> \n                        </ul><br>Thank you, <br>\n                    <strong>%company_name%</strong>', NULL, 0, NULL, NULL),
(114, 'customer_event_updated', NULL, 'enabled', 'sms', 'event', NULL, NULL, NULL, 'customer', '%event_name% Event Details Changed', 'Dear %customer_full_name%,\n                    \nDetails of the event on %event_start_date_time% have changed:\n    Organizer: %employee_full_name\n    Location: %location_name%\n\nThank you for choosing our company,\n%company_name%', NULL, 0, NULL, NULL),
(115, 'provider_event_updated', NULL, 'enabled', 'sms', 'event', NULL, NULL, NULL, 'provider', '%event_name% Event Details Changed', 'Hi %employee_full_name%,\n                \nDetails of the event on %event_start_date_time% have changed:\n    Description: %event_description%, \n    Location: %location_name%\n\nThank you,\n%company_name%', NULL, 0, NULL, NULL),
