(118, 'customer_invoice', NULL, 'enabled', 'email', 'appointment', NULL, NULL, NULL, 'customer', 'Booking Invoice', 'Dear <strong>%customer_full_name%</strong>,<br><br>Please find the attached invoice for your reference. If you have any questions, feel free to contact us.\n                    <br><br>Thank you for choosing our company, <br>\n                    <strong>%company_name%</strong>', NULL, 0, NULL, NULL);
